import{_ as o,c as a,o as i,af as r}from"./chunks/framework.KNbxCOYF.js";const v=JSON.parse('{"title":"用 Neovim 开发 Spring Boot 项目","description":"","frontmatter":{},"headers":[],"relativePath":"zh/programming/language/java/develop-spring-boot-project-with-neovim.md","filePath":"zh/programming/language/java/develop-spring-boot-project-with-neovim.md","lastUpdated":1768896337000}'),d={name:"zh/programming/language/java/develop-spring-boot-project-with-neovim.md"};function c(n,e,t,l,p,s){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="用-neovim-开发-spring-boot-项目" tabindex="-1">用 Neovim 开发 Spring Boot 项目 <a class="header-anchor" href="#用-neovim-开发-spring-boot-项目" aria-label="Permalink to &quot;用 Neovim 开发 Spring Boot 项目&quot;">​</a></h1><h2 id="在-neovim-中安装-java-用的-lsp-插件" tabindex="-1">在 Neovim 中安装 Java 用的 LSP 插件 <a class="header-anchor" href="#在-neovim-中安装-java-用的-lsp-插件" aria-label="Permalink to &quot;在 Neovim 中安装 Java 用的 LSP 插件&quot;">​</a></h2><p>Java 的 LSP 叫 <code>jdtls</code>。<br><code>nvim-lspconfig</code> 的文档提到，想要完整的 <code>jdtls</code> 体验需要用 <code>nvim-jdtls</code>。</p><p>两个插件都在 <code>lsp/</code> 目录下为 <code>jdtls</code> 做了配置。<br> 根据实测，先加载的插件的 <code>lsp/</code> 优先级高（数组全覆盖，对象是否会合并未验证）。</p><p><code>nvim-jdtls</code> 的 <code>README</code> 有安装 <code>jdtls</code> 的详细说明。<br> 因为项目中使用的 Java 版本可能低于 <code>nvim-jdtls</code> 所需的 JDK v21，<br> 区分多个版本需要在 LSP 配置的运行时相关部分硬编码 JDK 路径，<br> 环境变量设置项目所需的 JDK 版本即可。</p><p>相关的环境变量是 <code>JAVA_HOME</code> 和 <code>PATH</code>，<br> 一些情况下启动服务时会只看 <code>PATH</code> 中的 Java 程序，<br> 不过 <code>PATH</code> 里可以写为 <code>%JAVA_HOME%/bin</code>。</p><p><code>nvim-lspconfig</code> 现在是只提供 LSP 配置的插件，启动 LSP 服务器由 Neovim 内部完成。<br> 但是 <code>nvim-jdtls</code> 手动调用了 Neovim 的启动 LSP 服务器的 API，<br> 却没有出现重复的实例，推测是 Neovim 内部做了去重。</p><h2 id="使用-maven-启动-spring-boot-项目" tabindex="-1">使用 Maven 启动 Spring Boot 项目 <a class="header-anchor" href="#使用-maven-启动-spring-boot-项目" aria-label="Permalink to &quot;使用 Maven 启动 Spring Boot 项目&quot;">​</a></h2><ol><li>进入 <code>pom.xml</code> 所在的目录。</li><li>执行 <code>mvn [clean] spring-boot:run</code>。 <ul><li>如果项目内有 Maven Wrapper，多半会有 <code>mvnw</code> 文件。<br> 此时执行 <code>&lt;mvnw-path&gt; [clean] spring-boot:run</code>（Windows 下是 <code>mvnw.cmd</code>）。</li><li>不执行 <code>clean</code> 的话是增量编译，<br> 执行 <code>clean</code> 会删除之前的编译文件（<code>target/</code>）重新全量编译。</li><li>可以添加 <code>-Dspring-boot.run.profiles=local</code> 这样的参数来指定配置文件。 <ul><li>See: <a href="https://docs.spring.io/spring-boot/maven-plugin/run.html#run.examples.specify-active-profiles" target="_blank" rel="noreferrer">https://docs.spring.io/spring-boot/maven-plugin/run.html#run.examples.specify-active-profiles</a></li></ul></li></ul></li></ol><p>Maven Wrapper 会下载一个 Maven 到 <code>~/.m2</code> 里，其管理的依赖也会被下载到这里。<br><code>mvnw</code> 执行后的编译文件等物会放置在项目内执行命令的目录下新生成的 <code>target/</code> 里。</p>',10)])])}const g=o(d,[["render",c]]);export{v as __pageData,g as default};
